/**
 * The app's security headers (public/_headers, `/*`), set again on the box pages the edge function answers: Cloudflare's
 * docs say `_headers` does not apply to responses generated by Pages Functions. The site's explicit origin config
 * below is mirrored in public/_headers; share-headers.test.ts checks both. A deployment with different API or public
 * art origins must update both together. Server-only IPFS gateways need no browser permission: item art is verified
 * and served by the API. Never put gateway credentials or URLs containing keys in a browser policy.
 *
 * SH-258: a BNB Chain testnet build (`SH_TESTNET=bnb`) has its own policy (`testnetCspOrigins`): the build writes its
 * `_headers` from it (vite.config.ts, testnet-output.ts), and the edge function's headers follow the same profile.
 */
import { TESTNET, type TestnetProfile } from '../../../../packages/chain/src/config/testnet-profile.ts';
export interface CspOrigins {
  readonly api: readonly string[];
  readonly art: readonly string[];
  readonly rpc: readonly string[];
  /**
   * SH-ARWEAVE-PICTURES-WEB: connections only. Turbo's upload origin (Create and the box page publish a box's logo and
   * cover there) and the three Arweave gateways the pictures are searched and read on (pictures/arweave-hosts.ts). The
   * bytes are checked against their hash and drawn from a blob: URL, so img-src gains nothing.
   */
  readonly pictures?: readonly string[];
}

/** Public site configuration. Art currently uses the API; no direct IPFS gateway is exposed to the browser. */
const SEPOLIA_SITE_CSP_ORIGINS: CspOrigins = Object.freeze({
  api: Object.freeze(['https://api.squarehole.fun']),
  art: Object.freeze([]),
  rpc: Object.freeze(['https://ethereum-sepolia-rpc.publicnode.com', 'https://sepolia.gateway.tenderly.co']),
  pictures: Object.freeze(['https://upload.ardrive.io', 'https://turbo-gateway.com', 'https://arweave.net', 'https://goldsky.arweave.net']),
});

/**
 * SH-258: the policy of a build for another test network than Sepolia (BNB Chain testnet): its own read RPCs, and the
 * index (`api`) and picture gateway (`art`) origins its host names. SH-285: where the network keeps a box's logo and
 * cover on Arweave (`switches.arweavePictures`), the Sepolia site's own picture origins, the list the test site's server
 * reads (infra/server/app/config.mjs); none where it does not. This module imports nothing more: that server's release
 * tooling reads it with a fixed list of files.
 */
export function testnetCspOrigins(profile: TestnetProfile, named: { readonly api?: readonly string[]; readonly art?: readonly string[] } = {}): CspOrigins {
  return Object.freeze({
    api: Object.freeze([...(named.api ?? [])]),
    art: Object.freeze([...(named.art ?? [])]),
    rpc: Object.freeze(profile.publicRpcUrls.map((url) => new URL(url).origin)),
    pictures: profile.switches.arweavePictures ? SEPOLIA_SITE_CSP_ORIGINS.pictures ?? Object.freeze([]) : Object.freeze([]),
  });
}

/** The site's policy: Sepolia's as it was; another test network's from its profile (SH-258). */
export const SITE_CSP_ORIGINS: CspOrigins = TESTNET.name === 'sepolia' ? SEPOLIA_SITE_CSP_ORIGINS : testnetCspOrigins(TESTNET);

function origins(values: readonly string[]): string[] {
  return [...new Set(values.map((value) => {
    try {
      const url = new URL(value);
      const safe = url.protocol === 'https:' || (url.protocol === 'http:' && ['localhost', '127.0.0.1', '[::1]'].includes(url.hostname));
      if (!safe || value.includes('*') || value !== url.origin) throw new Error();
      return url.origin;
    } catch {
      throw new Error('CSP sources must be explicit origins');
    }
  }))];
}

export function securityHeadersFor(config: CspOrigins): Readonly<Record<string, string>> {
  const images = origins([...config.api, ...config.art]);
  const connections = origins([...config.api, ...config.art, ...config.rpc, ...(config.pictures ?? [])]);
  return Object.freeze({
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), payment=()',
    'Content-Security-Policy': [
      "default-src 'self'", "script-src 'self'", "style-src 'self' 'unsafe-inline'",
      ["img-src 'self' data: blob:", ...images].join(' '), "font-src 'self' data:",
      ["connect-src 'self'", ...connections].join(' '), "worker-src 'self' blob:",
      "object-src 'none'", "base-uri 'self'", "frame-ancestors 'none'", "form-action 'self'",
    ].join('; '),
  });
}

export const SPA_SECURITY_HEADERS = securityHeadersFor(SITE_CSP_ORIGINS);
